fn fizzbuzz(n: u32) -> Vec<String> {
    let mut out = Vec::new();
    for i in 1..=n {
        let word = match (i % 3, i % 5) {
            (0, 0) => "FizzBuzz".to_string(),
            (0, _) => "Fizz".to_string(),
            (_, 0) => "Buzz".to_string(),
            _ => i.to_string(),
        };
        out.push(word);
    }
    out
}

fn collatz_steps(n: u64) -> u32 {
    let mut n = n;
    let mut steps = 0;
    loop {
        if n == 1 {
            break steps;
        }
        n = if n % 2 == 0 { n / 2 } else { 3 * n + 1 };
        steps += 1;
    }
}

fn primes_below(n: u32) -> Vec<u32> {
    let n = n as usize;
    if n < 3 {
        return Vec::new();
    }
    let mut composite = vec![false; n];
    let mut primes = Vec::new();
    for i in 2..n {
        if composite[i] {
            continue;
        }
        primes.push(i as u32);
        let mut j = i * i;
        while j < n {
            composite[j] = true;
            j += i;
        }
    }
    primes
}

fn first_square_above(limit: u64) -> u64 {
    let mut root = 1;
    while root * root <= limit {
        root += 1;
    }
    root * root
}

unitTests:
test("fizzbuzz", || {
    let fb = fizzbuzz(15);
    check_eq(fb.len(), 15);
    check_eq(fb[..5].to_vec(), vec!["1", "2", "Fizz", "4", "Buzz"]);
    check_eq(fb[14].as_str(), "FizzBuzz");
    check_eq(fizzbuzz(0).len(), 0);
});

test("collatz", || {
    check_eq(collatz_steps(1), 0);
    check_eq(collatz_steps(6), 8);
    check_eq(collatz_steps(27), 111);
});

test("primes", || {
    check_eq(primes_below(20), vec![2, 3, 5, 7, 11, 13, 17, 19]);
    check_eq(primes_below(2), Vec::<u32>::new());
    check_eq(primes_below(1_000_000).len(), 78498);
});

test("squares", || {
    check_eq(first_square_above(10), 16);
    check_eq(first_square_above(16), 25);
    check_eq(first_square_above(0), 1);
    check_eq(first_square_above(999_999_999_999), 1_000_000_000_000);
});

